import { useState } from 'react'
import {
	Text,
	TouchableOpacity,
	View,
	LayoutChangeEvent,
	StyleProp,
	ViewStyle
} from 'react-native'
import Animated, { useAnimatedStyle, withSpring } from 'react-native-reanimated'
import { colors, Theme, useTheme } from '@/theme'
import { defineStyles } from '@/utils/defineStyles'

interface SegmentedControlProps {
	options: string[]
	selectedOption: string
	onOptionPress?: (option: string) => void
	style?: StyleProp<ViewStyle>
}

export const SegmentedControl = ({
	options,
	selectedOption,
	onOptionPress,
	style
}: SegmentedControlProps) => {
	const { theme } = useTheme()
	const [containerWidth, setContainerWidth] = useState(0)

	const internalPadding = 8
	const itemWidth =
		containerWidth > 0 ? (containerWidth - internalPadding) / options.length : 0

	const animatedSliderStyle = useAnimatedStyle(() => {
		if (containerWidth === 0) return { left: 0 }

		return {
			left: withSpring(
				itemWidth * options.indexOf(selectedOption) + internalPadding / 2
			)
		}
	}, [selectedOption, options, itemWidth, containerWidth])

	const handleLayout = (event: LayoutChangeEvent) => {
		setContainerWidth(event.nativeEvent.layout.width)
	}

	return (
		<View
			style={[
				styles.container(theme),
				{ paddingHorizontal: internalPadding / 2 },
				style
			]}
			onLayout={handleLayout}
		>
			{containerWidth > 0 && (
				<Animated.View
					style={[
						{
							width: itemWidth
						},
						animatedSliderStyle,
						styles.activeBox(theme)
					]}
				/>
			)}
			{options.map((option) => {
				return (
					<TouchableOpacity
						onPress={() => {
							onOptionPress?.(option)
						}}
						key={option}
						style={styles.labelContainer}
						activeOpacity={0.7}
					>
						<Text style={[styles.label(theme)]}>{option}</Text>
					</TouchableOpacity>
				)
			})}
		</View>
	)
}

const styles = defineStyles({
	container: (theme: Theme) => ({
		flexDirection: 'row',
		height: 38,
		backgroundColor: colors[theme].gray[50],
		borderRadius: 10,
		borderCurve: 'continuous'
	}),

	activeBox: (theme: Theme) => ({
		position: 'absolute',
		borderRadius: 8,
		height: '80%',
		top: '10%',
		backgroundColor: colors[theme].background
	}),
	labelContainer: {
		flex: 1,
		justifyContent: 'center',
		alignItems: 'center'
	},
	label: (theme: Theme) => ({
		fontSize: 16,
		fontWeight: '500',
		color: colors[theme].gray[900]
	})
})
